import (
	context "context"
	fern "github.com/go-pagination-offset-item-index/fern"
	fernclient "github.com/go-pagination-offset-item-index/fern/client"
)

client := fernclient.NewClient()
response, err := client.Plants.List(
	context.TODO(),
	&fern.ListPlantsRequest{
		Offset: fern.Int(
			1,
		),
		Count: fern.Int(
			1,
		),
	},
)

